    GoodSerializer +
    NonTailFmt +
    SPRoundTripDps +
    EquivSerializersGeneral {
    proof fn leaf_inv(&self)
        ensures
            self.unambiguous(),
            self.safe_inv(),
            self.serialize_inv(),
            self.serialize_dps_inv(),
            self.equiv_general_inv(),
    ;
}

/// Similar to [`Leaf`], but also includes parser strictness
