            self.unambiguous(),
            self.safe_inv(),
            self.sound_inv(),
            self.strict_inv(),
            self.nonmal_inv(),
            self.serialize_inv(),
            self.serialize_dps_inv(),
            self.equiv_general_inv(),
    ;
}

impl<Fmt: LeafNonMalleable> Leaf for Fmt {
    proof fn leaf_inv(&self) {
        self.nonmal_leaf_inv();
    }
}

